using Microsoft.EntityFrameworkCore;
namespace TheBarcode.Api;
public static class AccountingJournalBuilder
{
 public static async Task Ensure(AppDbContext db,bool demo){var a=await db.LedgerAccounts.Where(x=>x.IsDemo==demo&&x.Active).ToDictionaryAsync(x=>x.Code);if(a.Count==0)return;var existing=(await db.JournalEntries.Where(x=>x.IsDemo==demo&&x.SourceId!=null).Select(x=>x.SourceId!).ToListAsync()).ToHashSet();var sales=await db.Sales.AsNoTracking().Include(x=>x.Items).Include(x=>x.Payments).Where(x=>x.IsDemo==demo&&x.Status!="Held"&&x.Status!="PendingApproval").ToListAsync();foreach(var s in sales)if(!existing.Contains($"sale:{s.Id}")){var e=new JournalEntry{Date=DateOnly.FromDateTime(s.OccurredAt.LocalDateTime),SourceType="Sale",SourceId=$"sale:{s.Id}",Memo=$"Sale {s.ReceiptNumber}",IsDemo=demo};foreach(var p in s.Payments)e.Lines.Add(new JournalLine{AccountId=p.Method.Equals("M-Pesa",StringComparison.OrdinalIgnoreCase)?a["1010"].Id:a["1000"].Id,Description=p.Method,Debit=p.Amount});var paid=s.Payments.Sum(x=>x.Amount);if(s.Total>paid)e.Lines.Add(new JournalLine{AccountId=a["1100"].Id,Description="Customer receivable",Debit=s.Total-paid});e.Lines.Add(new JournalLine{AccountId=a["4000"].Id,Description="Sales revenue",Credit=s.Total});var cost=s.Items.Sum(x=>x.UnitCost*x.Quantity);if(cost>0){e.Lines.Add(new JournalLine{AccountId=a["5000"].Id,Description="Cost of goods sold",Debit=cost});e.Lines.Add(new JournalLine{AccountId=a["1200"].Id,Description="Inventory issued",Credit=cost});}db.JournalEntries.Add(e);}var expenses=await db.Expenses.AsNoTracking().Where(x=>x.IsDemo==demo&&x.Active&&x.Status=="Approved").ToListAsync();foreach(var x in expenses)if(!existing.Contains($"expense:{x.Id}")){var e=new JournalEntry{Date=x.Date,SourceType="Expense",SourceId=$"expense:{x.Id}",Memo=x.Description,IsDemo=demo};e.Lines.Add(new JournalLine{AccountId=a["6000"].Id,Description=x.Category,Debit=x.Amount});var paid=Math.Min(x.Amount,x.PaidAmount);if(paid>0)e.Lines.Add(new JournalLine{AccountId=a["1000"].Id,Description=x.Method,Credit=paid});if(x.Amount>paid)e.Lines.Add(new JournalLine{AccountId=a["2000"].Id,Description="Supplier payable",Credit=x.Amount-paid});db.JournalEntries.Add(e);}await db.SaveChangesAsync();}
}
